head.b:skin:
/*
==========================================================================
Blogger Theme: Mohamed Shaban El-Atmani — Ultra-Futuristic Glassmorphism
Author: Mohamed Shaban El-Atmani (@msalatmani)
Version: 3.0 Pro Complete Edition
==========================================================================
*/

:root {
  --bg-dark: #070811;
  --bg-card: rgba(18, 22, 41, 0.65);
  --bg-card-hover: rgba(28, 34, 60, 0.85);
  --border: rgba(0, 229, 255, 0.18);
  --border-glow: rgba(0, 229, 255, 0.5);
  --primary: #00e5ff;
  --secondary: #7c4dff;
  --accent: #ff007f;
  --text-main: #f0f4fc;
  --text-muted: #94a3b8;
  --gradient-primary: linear-gradient(135deg, #00e5ff 0%, #7c4dff 100%);
  --gradient-card: linear-gradient(145deg, rgba(255,255,255,0.04) 0%, rgba(255,255,255,0.01) 100%);
  --glass-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.5);
  --font-en: 'Inter', 'Outfit', sans-serif;
  --font-ar: 'Cairo', sans-serif;
}

/* Base Reset &amp; Smooth Scroll */
* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-en);
  line-height: 1.65;
  overflow-x: hidden;
  background-image: 
    radial-gradient(circle at 15% 15%, rgba(0, 229, 255, 0.07) 0%, transparent 40%),
    radial-gradient(circle at 85% 85%, rgba(124, 77, 255, 0.07) 0%, transparent 40%);
  background-attachment: fixed;
}

body[dir="rtl"] {
  font-family: var(--font-ar);
}

/* Interactive Background Canvas */
#bg-canvas {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  z-index: -1; pointer-events: none; opacity: 0.6;
}

/* Containers &amp; Global Utility */
.container { width: 90%; max-width: 1200px; margin: 0 auto; }
.gradient-text {
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.btn {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 12px 28px; border-radius: 50px; font-weight: 600;
  font-size: 0.95rem; text-decoration: none; cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  border: none; outline: none;
}
.btn-primary {
  background: var(--gradient-primary); color: #fff;
  box-shadow: 0 4px 20px rgba(0, 229, 255, 0.3);
}
.btn-primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(0, 229, 255, 0.5);
}
.btn-outline {
  background: rgba(255, 255, 255, 0.03); color: var(--text-main);
  border: 1px solid var(--border);
}
.btn-outline:hover {
  border-color: var(--primary); color: var(--primary);
  background: rgba(0, 229, 255, 0.08); transform: translateY(-3px);
}

/* Dual Language Rules */
body[dir="ltr"] .lang-ar { display: none !important; }
body[dir="rtl"] .lang-en { display: none !important; }

/* Navbar */
.navbar {
  position: fixed; top: 0; left: 0; width: 100%; z-index: 1000;
  background: rgba(7, 8, 17, 0.85); backdrop-filter: blur(15px);
  border-bottom: 1px solid var(--border); padding: 18px 0;
  transition: all 0.3s;
}
.nav-container { display: flex; justify-content: space-between; align-items: center; }
.logo { font-size: 1.4rem; font-weight: 800; text-decoration: none; color: var(--text-main); letter-spacing: -0.5px; }
.logo span { color: var(--primary); }
.nav-menu { display: flex; align-items: center; gap: 24px; list-style: none; }
.nav-link { color: var(--text-muted); text-decoration: none; font-size: 0.92rem; font-weight: 500; transition: color 0.3s; }
.nav-link:hover { color: var(--primary); }

.mobile-menu-toggle { display: none; font-size: 1.4rem; color: var(--text-main); cursor: pointer; }

.lang-toggle-btn {
  background: rgba(0, 229, 255, 0.1); border: 1px solid var(--border);
  color: var(--primary); padding: 6px 16px; border-radius: 20px;
  font-size: 0.85rem; font-weight: 700; cursor: pointer; transition: all 0.3s;
}
.lang-toggle-btn:hover { background: rgba(0, 229, 255, 0.25); transform: scale(1.03); }

/* Hero Section */
.hero-section {
  padding: 160px 0 90px; text-align: center; position: relative;
}
.hero-avatar-wrapper {
  position: relative; width: 120px; height: 120px; margin: 0 auto 24px;
}
.hero-avatar {
  width: 100%; height: 100%; border-radius: 50%; object-fit: cover;
  border: 3px solid var(--primary); box-shadow: 0 0 30px rgba(0, 229, 255, 0.4);
}
.hero-status-pulse {
  position: absolute; bottom: 4px; right: 4px; width: 18px; height: 18px;
  background: #00ff88; border-radius: 50%; border: 3px solid var(--bg-dark);
  box-shadow: 0 0 10px #00ff88;
}
body[dir="rtl"] .hero-status-pulse { right: auto; left: 4px; }

.hero-badge {
  display: inline-flex; align-items: center; gap: 8px;
  background: rgba(0, 229, 255, 0.08); border: 1px solid rgba(0, 229, 255, 0.25);
  color: var(--primary); font-size: 0.85rem; font-weight: 600;
  padding: 6px 18px; border-radius: 50px; margin-bottom: 24px;
}
.hero-title { font-size: 3.5rem; font-weight: 900; line-height: 1.15; margin-bottom: 20px; letter-spacing: -1px; }
.hero-subtitle { color: var(--text-muted); font-size: 1.2rem; max-width: 780px; margin: 0 auto 36px; line-height: 1.7; }
.hero-btns { display: flex; justify-content: center; gap: 16px; flex-wrap: wrap; }

/* Typewriter Cursor */
.typewriter-cursor {
  display: inline-block; width: 3px; background-color: var(--primary);
  margin-left: 4px; animation: blink 0.8s infinite;
}
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }

/* General Cards &amp; Grid */
.section-title { text-align: center; font-size: 2.2rem; font-weight: 800; margin-bottom: 12px; }
.section-desc { text-align: center; color: var(--text-muted); max-width: 650px; margin: 0 auto 50px; font-size: 1.05rem; }
.grid-3 { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 28px; }

.glass-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: 20px; padding: 32px; transition: all 0.4s ease;
  position: relative; overflow: hidden; backdrop-filter: blur(10px);
  box-shadow: var(--glass-shadow);
}
.glass-card:hover {
  border-color: var(--border-glow); transform: translateY(-6px);
  box-shadow: 0 15px 40px -10px rgba(0, 229, 255, 0.15);
}
.card-icon {
  width: 54px; height: 54px; border-radius: 14px;
  background: rgba(0, 229, 255, 0.1); border: 1px solid rgba(0, 229, 255, 0.2);
  display: flex; align-items: center; justify-content: center;
  color: var(--primary); font-size: 1.4rem; margin-bottom: 20px;
}
.card-title { font-size: 1.3rem; font-weight: 700; margin-bottom: 12px; }
.card-text { color: var(--text-muted); font-size: 0.95rem; line-height: 1.65; }

/* Stats Bar */
.stats-bar {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 20px; margin: 60px 0; padding: 30px;
  background: rgba(255,255,255,0.02); border: 1px solid var(--border); border-radius: 20px;
  text-align: center;
}
.stat-number { font-size: 2.5rem; font-weight: 900; color: var(--primary); }
.stat-label { color: var(--text-muted); font-size: 0.9rem; font-weight: 600; }

/* Blogger Posts Stream Design */
.blog-section { padding: 90px 0; border-top: 1px solid var(--border); }
.post-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: 18px; overflow: hidden; display: flex; flex-direction: column;
  transition: all 0.35s; backdrop-filter: blur(10px); height: 100%;
}
.post-card:hover { border-color: var(--primary); transform: translateY(-5px); box-shadow: 0 12px 35px rgba(0,229,255,0.1); }
.post-card-body { padding: 26px; flex: 1; display: flex; flex-direction: column; }
.post-card-meta { font-size: 0.82rem; color: var(--primary); margin-bottom: 10px; display: flex; gap: 12px; }
.post-card-title { font-size: 1.3rem; font-weight: 700; margin-bottom: 12px; line-height: 1.4; }
.post-card-title a { color: var(--text-main); text-decoration: none; transition: color 0.2s; }
.post-card-title a:hover { color: var(--primary); }
.post-card-snippet { color: var(--text-muted); font-size: 0.95rem; margin-bottom: 20px; flex: 1; }

/* Single Post Page Styling */
.single-post-container { max-width: 850px; margin: 140px auto 80px; padding: 0 20px; }
.single-post-title { font-size: 2.8rem; font-weight: 800; line-height: 1.25; margin-bottom: 20px; }
.single-post-meta { display: flex; gap: 20px; color: var(--text-muted); font-size: 0.9rem; padding-bottom: 20px; border-bottom: 1px solid var(--border); margin-bottom: 35px; }
.single-post-content { font-size: 1.1rem; line-height: 1.9; color: #cbd5e1; }
.single-post-content h2, .single-post-content h3 { color: var(--text-main); margin: 35px 0 16px; font-weight: 700; }
.single-post-content p { margin-bottom: 22px; }
.single-post-content blockquote {
  border-left: 4px solid var(--primary); padding: 18px 24px;
  background: rgba(0, 229, 255, 0.05); border-radius: 0 12px 12px 0;
  margin: 25px 0; color: var(--text-main); font-style: italic;
}
body[dir="rtl"] .single-post-content blockquote {
  border-left: none; border-right: 4px solid var(--primary);
  border-radius: 12px 0 0 12px;
}

/* Floating WhatsApp Action Button */
.whatsapp-float {
  position: fixed; bottom: 25px; right: 25px; z-index: 999;
  width: 56px; height: 56px; border-radius: 50%;
  background: #25d366; color: white; display: flex; align-items: center;
  justify-content: center; font-size: 1.8rem; text-decoration: none;
  box-shadow: 0 4px 20px rgba(37, 211, 102, 0.4); transition: transform 0.3s;
}
body[dir="rtl"] .whatsapp-float { right: auto; left: 25px; }
.whatsapp-float:hover { transform: scale(1.1); }

/* Footer */
.footer { padding: 60px 0 30px; border-top: 1px solid var(--border); background: #04050a; text-align: center; }
.footer-socials { display: flex; justify-content: center; gap: 16px; margin-bottom: 25px; flex-wrap: wrap; }
.social-btn {
  width: 44px; height: 44px; border-radius: 50%; background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border); display: flex; align-items: center; justify-content: center;
  color: var(--text-main); text-decoration: none; transition: all 0.3s;
}
.social-btn:hover { background: var(--gradient-primary); color: #fff; border-color: transparent; transform: translateY(-3px); }
.footer-copy { color: var(--text-muted); font-size: 0.88rem; }

/* Responsive Rules */
@media (max-width: 900px) {
  .hero-title { font-size: 2.4rem; }
  .nav-menu { display: none; }
  .mobile-menu-toggle { display: block; }
  .nav-menu.active {
    display: flex; flex-direction: column; position: absolute;
    top: 100%; left: 0; width: 100%; background: rgba(7, 8, 17, 0.95);
    padding: 20px; border-bottom: 1px solid var(--border);
  }
}

body.script:
const canvas = document.getElementById('bg-canvas');
if (canvas) {
  const ctx = canvas.getContext('2d');
  let width = canvas.width = window.innerWidth;
  let height = canvas.height = window.innerHeight;

  window.addEventListener('resize', () => {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  });

  const particles = [];
  for(let i=0; i<45; i++) {
    particles.push({
      x: Math.random() * width,
      y: Math.random() * height,
      vx: (Math.random() - 0.5) * 0.6,
      vy: (Math.random() - 0.5) * 0.6,
      radius: Math.random() * 2 + 1
    });
  }

  function animateParticles() {
    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#00e5ff';
    ctx.strokeStyle = 'rgba(0, 229, 255, 0.08)';

    particles.forEach((p, index) => {
      p.x += p.vx;
      p.y += p.vy;
      if(p.x < 0 || p.x > width) p.vx *= -1;
      if(p.y < 0 || p.y > height) p.vy *= -1;

      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI*2);
      ctx.fill();

      for(let j=index+1; j<particles.length; j++) {
        const p2 = particles[j];
        const dist = Math.hypot(p.x - p2.x, p.y - p2.y);
        if(dist < 130) {
          ctx.beginPath();
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
        }
      }
    });

    requestAnimationFrame(animateParticles);
  }
  animateParticles();
}

/* Language Switcher */
function toggleLanguage() {
  const htmlEl = document.documentElement;
  const currentDir = htmlEl.getAttribute('dir');
  if (currentDir === 'rtl') {
    htmlEl.setAttribute('dir', 'ltr');
    localStorage.setItem('pref_lang', 'en');
  } else {
    htmlEl.setAttribute('dir', 'rtl');
    localStorage.setItem('pref_lang', 'ar');
  }
}

/* Mobile Nav Drawer Toggle */
function toggleMobileMenu() {
  const menu = document.getElementById('navMenu');
  menu.classList.toggle('active');
}

/* Restore preferred language */
(function() {
  const savedLang = localStorage.getItem('pref_lang');
  if (savedLang === 'ar') {
    document.documentElement.setAttribute('dir', 'rtl');
  } else {
    document.documentElement.setAttribute('dir', 'ltr');
  }
})();
